{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'block_public_acls' attribute is not set, defaulting to false. This allows public ACLs to be applied to the bucket, potentially exposing data."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "Ensure S3 bucket has block public policy enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'block_public_policy' attribute is not set, defaulting to false. This allows public bucket policies to be applied, which can lead to unintended data exposure."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "Ensure S3 bucket has ignore public ACLs enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'ignore_public_acls' attribute is not set, defaulting to false. Public ACLs are not ignored, meaning they can still grant access if present."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Ensure S3 bucket has 'restrict_public_buckets' enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'restrict_public_buckets' attribute is explicitly set to false. This allows public bucket policies and ACLs to override other settings, creating a significant security risk."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket                  = aws_s3_bucket.api_docs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Enabled all four public access block settings (block_public_acls, block_public_policy, ignore_public_acls, restrict_public_buckets) by setting them to true to prevent unauthorized public access to the S3 bucket."
}
